def record_conversation_operation(
    self,
    metric: TelegramConversationMetricRecord,
) -> None:
    error_category = (
        metric.error_category
        or "none"
    )

    self.increment(
        "inna_telegram_operations_total",
        labels={
            "component": metric.component,
            "operation": metric.operation,
            "outcome": metric.outcome,
            "error_category": error_category,
        },
    )

    duration_seconds = max(
        0.0,
        float(
            metric.duration_ms
        )
        / 1000.0,
    )

    self.observe(
        (
            "inna_telegram_"
            "operation_duration_seconds"
        ),
        duration_seconds,
        labels={
            "component": metric.component,
            "operation": metric.operation,
            "outcome": metric.outcome,
        },
    )

    if metric.outcome in {
        "error",
        "conflict",
    }:
        self.increment(
            "inna_telegram_failures_total",
            labels={
                "component": metric.component,
                "operation": metric.operation,
                "error_category": (
                    error_category
                ),
            },
        )

    if (
        metric.outcome
        in {
            "conflict",
            "recovered",
        }
        or metric.conflict_recovered
        is True
    ):
        conflict_outcome = (
            "recovered"
            if metric.conflict_recovered
            is True
            else metric.outcome
        )

        self.increment(
            "inna_telegram_conflicts_total",
            labels={
                "operation": metric.operation,
                "outcome": conflict_outcome,
            },
        )
